class Counter {
  count = 0;
  label = "c";
  inc = () => { this.count++; };
  add = (by: number) => { this.count += by; };
  show = () => this.label + this.count;
  double = (x: number) => { return x * 2; };
}
function main(): void {
  const c = new Counter();
  c.inc(); c.add(5);
  const f = c.show;
  console.log(f(), c.double(4));
}
